dashboard.definition:
{
    "title": "Operational Intelligence",
    "description": "Coordinate test health, path quality, routing instability, and AI Defense signals.",
    "inputs": {
        "input_time_range": {
            "options": {
                "defaultValue": "-24h@h,now,auto",
                "showAdvanced": true,
                "selections": [
                    {
                        "value": "-4h,now,auto",
                        "label": "4h"
                    },
                    {
                        "value": "-24h@h,now,auto",
                        "label": "24h"
                    },
                    {
                        "value": "-48h,now,auto",
                        "label": "48h"
                    },
                    {
                        "value": "-7d@d,now,auto",
                        "label": "7d"
                    },
                    {
                        "value": "-30d@d,now,auto",
                        "label": "30d"
                    }
                ],
                "token": "time_tok"
            },
            "title": "Time range",
            "type": "input.simpleTimePicker"
        }
    },
    "defaults": {
        "visualizations": {
            "global": {
                "showLastUpdated": true,
                "showProgressBar": true
            }
        }
    },
    "visualizations": {
        "viz_header_bg": {
            "type": "splunk.rectangle",
            "options": {
                "fillColor": "#1c2738",
                "strokeColor": "rgba(100,158,245,0.28)",
                "rx": 10
            }
        },
        "viz_header_icon": {
            "type": "splunk.image",
            "title": "Operational Intelligence",
            "options": {
                "preserveAspectRatio": true,
                "src": "/static/app/splunk-cisco-dashboards/images/nav-icons/RobotFaceSparkle.svg"
            }
        },
        "viz_header": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#ecf0f5",
                "markdown": "# Operational Intelligence\nCoordinate test health, path quality, routing instability, and AI Defense signals\\."
            }
        },
        "viz_card_01_background": {
            "type": "splunk.rectangle",
            "options": {
                "fillColor": "#131a23",
                "strokeColor": "rgba(100,158,245,0.28)",
                "rx": 12
            }
        },
        "viz_card_01_title": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#ecf0f5",
                "fontSize": "custom",
                "customFontSize": 20,
                "markdown": "**Degraded ThousandEyes Tests**"
            }
        },
        "viz_card_01_metadata": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#649ef5",
                "fontSize": "custom",
                "customFontSize": 14,
                "markdown": "Network  •  Agentic Ops"
            }
        },
        "viz_card_01_description": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#a6adb6",
                "fontSize": "custom",
                "customFontSize": 15,
                "markdown": "Lists the monitored ThousandEyes tests whose observed availability or loss crosses the documented degradation thresholds\\."
            }
        },
        "viz_card_01_singlevalue": {
            "type": "splunk.singlevalue",
            "title": "",
            "dataSources": {
                "primary": "ds_story_01"
            },
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "majorColor": "#ecf0f5",
                "majorFontSize": 44,
                "majorValue": "> primary | seriesByName(\"DegradedTests\") | lastPoint() | divideBy(0.999999999999)",
                "shouldAbbreviateMajorValue": true,
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "showTrendIndicator": false,
                "unit": " degraded tests",
                "unitPosition": "after"
            },
            "context": {
                "trendColorEditorConfig": [
                    {
                        "value": "#4cbf7f",
                        "to": -0.000001
                    },
                    {
                        "value": "#a6adb6",
                        "from": -0.000001,
                        "to": 0.000001
                    },
                    {
                        "value": "#f7782f",
                        "from": 0.000001
                    }
                ]
            }
        },
        "viz_card_01_trend": {
            "type": "splunk.table",
            "title": "Tests needing attention",
            "dataSources": {
                "primary": "ds_story_01"
            },
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "#131a23",
                "columnFormat": {
                    "Latest Availability %": {
                        "width": 130
                    },
                    "Peak Loss %": {
                        "width": 100
                    },
                    "Status": {
                        "width": 90
                    },
                    "Test": {
                        "width": 250
                    }
                },
                "count": 5,
                "fontSize": "small",
                "headerVisibility": "fixed",
                "showInternalFields": false,
                "showRowNumbers": false,
                "table": "> primary | frameBySeriesNames(\"Test\", \"Latest Availability %\", \"Peak Loss %\", \"Status\")",
                "tableFormat": {
                    "headerBackgroundColor": "#1c2738",
                    "headerColor": "#ecf0f5"
                }
            }
        },
        "viz_card_01_drilldown_trigger": {
            "type": "splunk.rectangle",
            "eventHandlers": [
                {
                    "type": "drilldown.customUrl",
                    "options": {
                        "url": "/drilldown?origin=Degraded%20ThousandEyes%20Tests&target=Secure%20Networking%20-%20ThousandEyes%20HTTP%20Availability%20by%20Test,Secure%20Networking%20-%20ThousandEyes%20HTTP%20Trace%20Log"
                    }
                }
            ],
            "options": {
                "fillColor": "transparent",
                "strokeColor": "transparent"
            },
            "context": {},
            "containerOptions": {},
            "showProgressBar": false,
            "showLastUpdated": false
        },
        "viz_card_01_info_trigger": {
            "type": "splunk.rectangle",
            "eventHandlers": [
                {
                    "type": "drilldown.customUrl",
                    "options": {
                        "url": "/metric-info?origin=Degraded%20ThousandEyes%20Tests&target=secure_networking_thousandeyes_test_health_summary"
                    }
                }
            ],
            "options": {
                "fillColor": "transparent",
                "strokeColor": "transparent"
            },
            "context": {},
            "containerOptions": {},
            "showProgressBar": false,
            "showLastUpdated": false
        },
        "viz_card_02_background": {
            "type": "splunk.rectangle",
            "options": {
                "fillColor": "#131a23",
                "strokeColor": "rgba(100,158,245,0.28)",
                "rx": 12
            }
        },
        "viz_card_02_title": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#ecf0f5",
                "fontSize": "custom",
                "customFontSize": 20,
                "markdown": "**AI Defense Policy Outcomes**"
            }
        },
        "viz_card_02_metadata": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#649ef5",
                "fontSize": "custom",
                "customFontSize": 14,
                "markdown": "Security  •  GenAI Protection"
            }
        },
        "viz_card_02_description": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#a6adb6",
                "fontSize": "custom",
                "customFontSize": 15,
                "markdown": "Time series trend of Cisco AI Defense Block vs Allow decisions\\. Useful to spot bursts of denied prompts \\(likely attack/probing\\) against the steady\\-state allow baseline\\."
            }
        },
        "viz_card_02_singlevalue": {
            "type": "splunk.singlevalue",
            "title": "",
            "dataSources": {
                "primary": "ds_story_02"
            },
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "majorColor": "#ecf0f5",
                "majorFontSize": 44,
                "majorValue": "> primary | seriesByName(\"WindowBlocked\") | lastPoint() | divideBy(0.999999999999)",
                "shouldAbbreviateMajorValue": true,
                "sparklineDisplay": "off",
                "trendDisplay": "absolute",
                "shouldAbbreviateTrendValue": true,
                "showTrendIndicator": true,
                "sparklineValues": "> primary | seriesByName(\"Blocked\")",
                "trendColor": "> trendValue | rangeValue(trendColorEditorConfig)",
                "trendFontSize": 28,
                "trendValue": "> sparklineValues | delta(-2)",
                "unit": " blocked decisions",
                "unitPosition": "after"
            },
            "context": {
                "trendColorEditorConfig": [
                    {
                        "value": "#049fd9",
                        "to": 0
                    },
                    {
                        "value": "#049fd9",
                        "from": 0
                    }
                ]
            }
        },
        "viz_card_02_trend": {
            "type": "splunk.column",
            "title": "",
            "dataSources": {
                "primary": "ds_story_02"
            },
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "legendDisplay": "bottom",
                "seriesColorsByField": {
                    "Allowed": "#159352",
                    "Blocked": "#e44273",
                    "Other": "#a9afda"
                },
                "seriesColors": [
                    "#9b5ff4",
                    "#3abdfa",
                    "#0d8e97",
                    "#e2a811",
                    "#e44273",
                    "#a9afda",
                    "#d8580f",
                    "#f88ddc",
                    "#159352",
                    "#9abe2d",
                    "#6574f3",
                    "#ff9297",
                    "#d14baf",
                    "#24c4c9",
                    "#bb6e04",
                    "#6ec641",
                    "#777daf",
                    "#ff9755",
                    "#698c07",
                    "#c69fff"
                ],
                "dataValuesDisplay": "off",
                "stackMode": "stacked",
                "showYMajorGridLines": false,
                "xAxisTitleVisibility": "hide",
                "yAxisTitleVisibility": "hide",
                "x": "> primary | seriesByName(\"_time\")",
                "y": "> primary | frameBySeriesNames(\"Allowed\", \"Blocked\", \"Other\")",
                "showYMinorGridLines": false,
                "yAxisLabelVisibility": "hide",
                "yAxisLineVisibility": "hide",
                "yAxisMajorTickVisibility": "hide",
                "yAxisMinorTickVisibility": "hide"
            }
        },
        "viz_card_02_drilldown_trigger": {
            "type": "splunk.rectangle",
            "eventHandlers": [
                {
                    "type": "drilldown.customUrl",
                    "options": {
                        "url": "/drilldown?origin=AI%20Defense%20Policy%20Outcomes&target=Security%20-%20GenAI%20Protection%20-%20Cisco%20AI%20Defense%20Top%20Blocked%20Policies,Security%20-%20GenAI%20Protection%20-%20Cisco%20AI%20Defense%20Recent%20Blocked%20Messages"
                    }
                }
            ],
            "options": {
                "fillColor": "transparent",
                "strokeColor": "transparent"
            },
            "context": {},
            "containerOptions": {},
            "showProgressBar": false,
            "showLastUpdated": false
        },
        "viz_card_02_info_trigger": {
            "type": "splunk.rectangle",
            "eventHandlers": [
                {
                    "type": "drilldown.customUrl",
                    "options": {
                        "url": "/metric-info?origin=AI%20Defense%20Policy%20Outcomes&target=security_ai_defense_action_trend"
                    }
                }
            ],
            "options": {
                "fillColor": "transparent",
                "strokeColor": "transparent"
            },
            "context": {},
            "containerOptions": {},
            "showProgressBar": false,
            "showLastUpdated": false
        },
        "viz_card_03_background": {
            "type": "splunk.rectangle",
            "options": {
                "fillColor": "#131a23",
                "strokeColor": "rgba(100,158,245,0.28)",
                "rx": 12
            }
        },
        "viz_card_03_title": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#ecf0f5",
                "fontSize": "custom",
                "customFontSize": 20,
                "markdown": "**Latency by Reporting Agent**"
            }
        },
        "viz_card_03_metadata": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#649ef5",
                "fontSize": "custom",
                "customFontSize": 14,
                "markdown": "Network  •  Agentic Ops"
            }
        },
        "viz_card_03_description": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#a6adb6",
                "fontSize": "custom",
                "customFontSize": 15,
                "markdown": "Ranks ThousandEyes reporting agent locations by selected\\-window p95 network latency so the worst observed paths are immediately identifiable\\."
            }
        },
        "viz_card_03_singlevalue": {
            "type": "splunk.singlevalue",
            "title": "",
            "dataSources": {
                "primary": "ds_story_03"
            },
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "majorColor": "#ecf0f5",
                "majorFontSize": 44,
                "majorValue": "> primary | seriesByName(\"WindowPeakLatencyMs\") | lastPoint()",
                "shouldAbbreviateMajorValue": true,
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "showTrendIndicator": false,
                "unit": " ms",
                "unitPosition": "after"
            },
            "context": {
                "trendColorEditorConfig": [
                    {
                        "value": "#4cbf7f",
                        "to": -0.000001
                    },
                    {
                        "value": "#a6adb6",
                        "from": -0.000001,
                        "to": 0.000001
                    },
                    {
                        "value": "#f7782f",
                        "from": 0.000001
                    }
                ]
            }
        },
        "viz_card_03_trend": {
            "type": "splunk.bar",
            "title": "",
            "dataSources": {
                "primary": "ds_story_03"
            },
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "legendDisplay": "off",
                "seriesColors": [
                    "#e2a811",
                    "#3abdfa",
                    "#0d8e97",
                    "#9b5ff4",
                    "#e44273",
                    "#a9afda",
                    "#d8580f",
                    "#f88ddc",
                    "#159352",
                    "#9abe2d",
                    "#6574f3",
                    "#ff9297",
                    "#d14baf",
                    "#24c4c9",
                    "#bb6e04",
                    "#6ec641",
                    "#777daf",
                    "#ff9755",
                    "#698c07",
                    "#c69fff"
                ],
                "dataValuesDisplay": "all",
                "stackMode": "unstacked",
                "showYMajorGridLines": false,
                "xAxisTitleVisibility": "hide",
                "yAxisTitleVisibility": "hide",
                "x": "> primary | seriesByName(\"Agent\")",
                "y": "> primary | seriesByName(\"P95 Latency ms\")",
                "showYMinorGridLines": false,
                "yAxisLabelVisibility": "hide",
                "yAxisLineVisibility": "hide",
                "yAxisMajorTickVisibility": "hide",
                "yAxisMinorTickVisibility": "hide"
            }
        },
        "viz_card_03_drilldown_trigger": {
            "type": "splunk.rectangle",
            "eventHandlers": [
                {
                    "type": "drilldown.customUrl",
                    "options": {
                        "url": "/drilldown?origin=Latency%20by%20Reporting%20Agent&target=Secure%20Networking%20-%20ThousandEyes%20Latency%20by%20Agent%20Location"
                    }
                }
            ],
            "options": {
                "fillColor": "transparent",
                "strokeColor": "transparent"
            },
            "context": {},
            "containerOptions": {},
            "showProgressBar": false,
            "showLastUpdated": false
        },
        "viz_card_03_info_trigger": {
            "type": "splunk.rectangle",
            "eventHandlers": [
                {
                    "type": "drilldown.customUrl",
                    "options": {
                        "url": "/metric-info?origin=Latency%20by%20Reporting%20Agent&target=secure_networking_thousandeyes_latency_by_agent_summary"
                    }
                }
            ],
            "options": {
                "fillColor": "transparent",
                "strokeColor": "transparent"
            },
            "context": {},
            "containerOptions": {},
            "showProgressBar": false,
            "showLastUpdated": false
        },
        "viz_card_04_background": {
            "type": "splunk.rectangle",
            "options": {
                "fillColor": "#131a23",
                "strokeColor": "rgba(100,158,245,0.28)",
                "rx": 12
            }
        },
        "viz_card_04_title": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#ecf0f5",
                "fontSize": "custom",
                "customFontSize": 20,
                "markdown": "**Network Loss**"
            }
        },
        "viz_card_04_metadata": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#649ef5",
                "fontSize": "custom",
                "customFontSize": 14,
                "markdown": "Network  •  Agentic Ops"
            }
        },
        "viz_card_04_description": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#a6adb6",
                "fontSize": "custom",
                "customFontSize": 15,
                "markdown": "Hourly trend of average and maximum network packet loss from Cisco ThousandEyes, enabling detection of transient vs sustained path quality degradation over time\\."
            }
        },
        "viz_card_04_singlevalue": {
            "type": "splunk.singlevalue",
            "title": "",
            "dataSources": {
                "primary": "ds_story_04"
            },
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "majorColor": "#ecf0f5",
                "majorFontSize": 44,
                "majorValue": "> primary | seriesByName(\"WindowAvgLossPct\") | lastPoint() | divideBy(0.999999999999)",
                "numberPrecision": 2,
                "shouldAbbreviateMajorValue": false,
                "sparklineDisplay": "off",
                "trendDisplay": "absolute",
                "shouldAbbreviateTrendValue": true,
                "showTrendIndicator": true,
                "sparklineValues": "> primary | seriesByName(\"avg_loss_pct\")",
                "trendColor": "> trendValue | rangeValue(trendColorEditorConfig)",
                "trendFontSize": 28,
                "trendValue": "> sparklineValues | delta(-2)",
                "unit": "%"
            },
            "context": {
                "trendColorEditorConfig": [
                    {
                        "value": "#4cbf7f",
                        "to": -0.000001
                    },
                    {
                        "value": "#a6adb6",
                        "from": -0.000001,
                        "to": 0.000001
                    },
                    {
                        "value": "#f7782f",
                        "from": 0.000001
                    }
                ]
            }
        },
        "viz_card_04_trend": {
            "type": "splunk.line",
            "title": "",
            "dataSources": {
                "primary": "ds_story_04"
            },
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "legendDisplay": "bottom",
                "seriesColors": [
                    "#3abdfa",
                    "#9b5ff4",
                    "#0d8e97",
                    "#e2a811",
                    "#e44273",
                    "#a9afda",
                    "#d8580f",
                    "#f88ddc",
                    "#159352",
                    "#9abe2d",
                    "#6574f3",
                    "#ff9297",
                    "#d14baf",
                    "#24c4c9",
                    "#bb6e04",
                    "#6ec641",
                    "#777daf",
                    "#ff9755",
                    "#698c07",
                    "#c69fff"
                ],
                "dataValuesDisplay": "minmax",
                "lineWidth": 2,
                "markerDisplay": "outlined",
                "nullValueDisplay": "connect",
                "showYMajorGridLines": false,
                "xAxisTitleVisibility": "hide",
                "yAxisTitleVisibility": "hide",
                "x": "> primary | seriesByName(\"_time\")",
                "y": "> primary | frameBySeriesNames(\"avg_loss_pct\", \"max_loss_pct\")",
                "showYMinorGridLines": false,
                "yAxisLabelVisibility": "hide",
                "yAxisLineVisibility": "hide",
                "yAxisMajorTickVisibility": "hide",
                "yAxisMinorTickVisibility": "hide"
            }
        },
        "viz_card_04_drilldown_trigger": {
            "type": "splunk.rectangle",
            "eventHandlers": [
                {
                    "type": "drilldown.customUrl",
                    "options": {
                        "url": "/drilldown?origin=Network%20Loss&target=Secure%20Networking%20-%20ThousandEyes%20Latency%20by%20Agent%20Location,Secure%20Networking%20-%20ThousandEyes%20HTTP%20Trace%20Log"
                    }
                }
            ],
            "options": {
                "fillColor": "transparent",
                "strokeColor": "transparent"
            },
            "context": {},
            "containerOptions": {},
            "showProgressBar": false,
            "showLastUpdated": false
        },
        "viz_card_04_info_trigger": {
            "type": "splunk.rectangle",
            "eventHandlers": [
                {
                    "type": "drilldown.customUrl",
                    "options": {
                        "url": "/metric-info?origin=Network%20Loss&target=secure_networking_thousandeyes_network_loss_trend"
                    }
                }
            ],
            "options": {
                "fillColor": "transparent",
                "strokeColor": "transparent"
            },
            "context": {},
            "containerOptions": {},
            "showProgressBar": false,
            "showLastUpdated": false
        },
        "viz_card_05_background": {
            "type": "splunk.rectangle",
            "options": {
                "fillColor": "#131a23",
                "strokeColor": "rgba(100,158,245,0.28)",
                "rx": 12
            }
        },
        "viz_card_05_title": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#ecf0f5",
                "fontSize": "custom",
                "customFontSize": 20,
                "markdown": "**Lowest Application Availability**"
            }
        },
        "viz_card_05_metadata": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#649ef5",
                "fontSize": "custom",
                "customFontSize": 14,
                "markdown": "Network  •  Agentic Ops"
            }
        },
        "viz_card_05_description": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#a6adb6",
                "fontSize": "custom",
                "customFontSize": 15,
                "markdown": "Ranks monitored ThousandEyes tests by their lowest observed HTTP availability and retains average and latest values in the metric detail\\."
